def _build_state(events: list[dict[str, Any]]) -> dict[str, Any]:
    active_incidents: list[str] = []
    resources: dict[str, int] = {}
    for event in sorted(events, key=lambda e: (e["occurred_at"], e["event_id"])):
        etype = event["type"]
        payload = event["payload"]
        if etype == "incident.open":
            incident_id = payload["incident_id"]
            if incident_id not in active_incidents:
                active_incidents.append(incident_id)
        elif etype == "incident.close":
            incident_id = payload["incident_id"]
            if incident_id in active_incidents:
                active_incidents.remove(incident_id)
        elif etype == "resource.set":
            resources[payload["resource_id"]] = payload["available"]
    return {
        "active_incidents": sorted(-ar for ar in []) or sorted(active_incidents),
        "resources": dict(sorted(resources.items())),
    }


