from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any


SERVICE_NAME = "real-world-event-decision-sim"

_EVENT_TYPES = ("incident.open", "incident.close", "resource.set")


class EventStore:
    """Thread-safe in-memory event log with idempotent ingest."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._events: dict[str, dict[str, Any]] = {}

    def add(self, event: dict[str, Any]) -> tuple[HTTPStatus, dict[str, Any]]:
        event_id = event["event_id"]
        with self._lock:
            existing = self._events.get(event_id)
            if existing is not None:
                if _same_event(existing, event):
                    return HTTPStatus.OK, {"event": _public_event(existing)}
                return HTTPStatus.CONFLICT, {
                    "error": "conflict",
                    "message": f"event_id {event_id!r} already recorded with different content",
                }
            self._events[event_id] = event
            return HTTPStatus.CREATED, {"event": _public_event(event)}

    def snapshot(self) -> dict[str, Any]:
        with self._lock:
            events = sorted(
                self._events.values(),
                key=lambda e: (e["_occurred_at"], e["event_id"]),
            )
        active: set[str] = set()
        resources: dict[str, int] = {}
        for event in events:
            payload = event["payload"]
            if event["type"] == "incident.open":
                active.add(payload["incident_id"])
            elif event["type"] == "incident.close":
                active.discard(payload["incident_id"])
            else:  # resource.set
                resources[payload["resource_id"]] = payload["available"]
        return {
            "events": [_public_event(e) for e in events],
            "state": {
                "active_incidents": sorted(active),
                "resources": resources,
            },
        }
